# Verses the Vulgate divides its own way, the same in DRC1752 and CPDV (both
# read against NIV and LSG; Douay-Rheims words quoted).
# Numbers 15:15 holds "one law and judgment" (15:15-16); 15:17-18 split
# "Speak to the children of Israel" / "When you are come into the land".
NUM 15:1-15 = NUM 15:1-15
NUM 15:16 = NUM 15:17
NUM 15:17 = NUM 15:18
NUM 15:18 = NUM 15:18
NUM 15:19-41 = NUM 15:19-41
# Numbers 27:3 holds the daughters' plea (27:3-4); 27:7-8 split "to the
# children of Israel thou shalt speak" / "When a man dieth without a son".
NUM 27:1-3 = NUM 27:1-3
NUM 27:4-7 = NUM 27:5-8
NUM 27:8 = NUM 27:8
NUM 27:9-23 = NUM 27:9-23
# Deuteronomy 6:12, "And thou shalt have eaten and be full", ends 6:11, and
# 6:13 runs from "Take heed diligently lest thou forget the Lord" (6:12-13).
DEU 6:1-11 = DEU 6:1-11
DEU 6:12 = DEU 6:11
DEU 6:13 = DEU 6:12
DEU 6:14-25 = DEU 6:14-25
# 1 Chronicles 11:32 runs on through Azmoth and Eliaba (11:32-33), and
# 11:34-35 split Ahiam and Eliphal (11:35).
1CH 11:1-32 = 1CH 11:1-32
1CH 11:33 = 1CH 11:34
1CH 11:34 = 1CH 11:35
1CH 11:35 = 1CH 11:35
1CH 11:36-46 = 1CH 11:36-46
# Nehemiah 7:44 is "Of Oduia, seventy-four", the end of 7:43, so the singers,
# porters and Nathinites run one behind until 7:48 holds 7:47-48; 7:68 is
# the horses and mules, numbered as in English.
NEH 7:1-43 = NEH 7:1-43
NEH 7:44 = NEH 7:43
NEH 7:45-48 = NEH 7:44-47
NEH 7:49-68 = NEH 7:49-68
NEH 7:69-73 = NEH 7:68-72
# Psalm 108 (Hebrew 109): 108:16-17 split "he remembered not to shew mercy"
# / "But persecuted the poor man", and 108:18 runs on through "he put on
# cursing" (109:17-18).
PSA 108:1-16 = PSA 109:1-16
PSA 108:17 = PSA 109:16
PSA 108:18 = PSA 109:17
PSA 108:19-31 = PSA 109:19-31
# Luke 9:42-43 split "the devil threw him down" / "Jesus rebuked the unclean
# spirit", and 9:44 is "all were astonished" (9:43).
LUK 9:1-42 = LUK 9:1-42
LUK 9:43 = LUK 9:42
LUK 9:44 = LUK 9:43
LUK 9:45-62 = LUK 9:45-62
# 2 Timothy 4:8 ends with "Make haste to come to me quickly" (4:9), and
# 4:9-10 split Demas from Crescens and Titus (4:10).
2TI 4:1-8 = 2TI 4:1-8
2TI 4:9 = 2TI 4:10
2TI 4:10 = 2TI 4:10
2TI 4:11-22 = 2TI 4:11-22
